document.addEventListener("DOMContentLoaded",function(){const e=window.location.origin,i=document.querySelector(".aios-repopulate-widgets");new Date().toLocaleString(),i.addEventListener("click",function(l){l.preventDefault();const a=Swal.mixin({customClass:{confirmButton:"btn btn-success",cancelButton:"btn btn-danger"},buttonsStyling:!1});a.fire({title:"Are you sure?",text:"Doing This will Delete Form, Current Menu and Slideshow",icon:"warning",showCancelButton:!0,confirmButtonText:"Proceed!",cancelButtonText:"Cancel!",reverseButtons:!0,allowOutsideClick:!1}).then(s=>{s.isConfirmed?Swal.fire({title:"Please wait for as we setup your theme ",html:`<div class="lds-facebook"><div></div><div></div><div></div></div><a href="${e}" class="wpui-secondary-button text-uppercase auto-populate-api-status">Visit Homepage</a>`,showConfirmButton:!1,allowOutsideClick:!1,didOpen:()=>{window.addEventListener("beforeunload",function(t){t.preventDefault(),t.returnValue="There are pending requests. Are you sure you want to leave this page?"}),(async()=>{const t=`${e}/wp-json/aios-populate/v1/widgets`,r=`${e}/wp-json/aios-populate/v1/form`,u=`${e}/wp-json/aios-populate/v1/menu`,c=`${e}/wp-json/aios-populate/v1/regeneratecontents`,d={"Content-Type":"application/json"},p={repopulate:!0,date:new Date().toLocaleString()};try{const o=[t,r,u,c].map(n=>fetch(n,{method:"POST",headers:d,body:JSON.stringify(p)})),w=(await Promise.all(o)).map(n=>n.json()),h=await Promise.all(w);$buttonStatus=Swal.getPopup().querySelector(".auto-populate-api-status"),$loader=Swal.getPopup().querySelector(".lds-facebook"),$title=Swal.getPopup().querySelector(".swal2-title"),$loader.style.display="none",$title.textContent="Your theme setup is already done. Please click the link below to proceed.",$buttonStatus.style.display="inline-block"}catch(o){console.error("Error fetching data:",o)}})()}}):s.dismiss===Swal.DismissReason.cancel&&a.fire({title:"Cancelled",icon:"error"})})})});
